/* Isolated UI state only. No persistence, scoring, model calls or profile writes. */
window.AssessmentPreview=(()=>{
 'use strict';
 const {esc,icon,button:B,link:L,top,bottle}=UI;
 let C;const state={factor:null,count:3,screen:{},answer:{},scores:{}};
 const names={'single-factor':'单因子测评','daily-checkin':'每日打卡','short-16pf':'简化版16PF','personality-sandbox':'模拟性格','ai-reset':'AI 重置版'};
 const tag=t=>`<span class="preview-status">${t}</span>`;
 const head=(route,desc)=>`${top('认识')}<header class="preview-heading"><h1>${names[route]}</h1><p>${desc}</p></header>`;
 const unavailable=(label,why)=>`<div class="preview-unavailable">${B('暂不可用','preview-unavailable',{cls:'btn full',disabled:true})}</div>`;
 const controls=(route,label='开始作答')=>ProductContext.fixture?B(label,'preview-stage',{cls:'btn secondary full','data-id':route,'data-stage':'process',after:'arrow'}):'';
 function home(s){
  const sess=s.sessions.find(x=>x.id===s.activeSession&&(ProductContext.fixture||x.kind!=='interaction-demo')),unfinished=sess?.status==='in-progress',done=sess?.status==='completed',a=s.actions.find(x=>x.status==='active'),ai=s.mode==='ai';
  const action=ai?'nav':unfinished?'resume':done?'nav':'start',params=ai?{'data-route':'ai-reset'}:done?{'data-route':'review','data-id':sess.id}:{};
  return `<header class="v3-home-heading"><h1>你好，今天的你</h1><p>留一点时间，认识自己</p></header><section class="home-scene" aria-label="16PF 性格探索"><div class="home-portrait"><div class="v4-person-scene" aria-hidden="true"><span></span><i></i><i></i><img src="assets/person-${s.avatar}.svg" alt=""></div></div><div class="home-assessment"><h2>16PF 性格探索</h2><p class="assessment-purpose">${ai?'AI 重置版的题目表达与作答说明仍在准备中。开放后可先查看版本说明，再决定是否开始。':'从16个角度，了解自己思考、感受和与人相处的倾向。结合日常经历，看看自己习惯怎样回应不同情境。'}</p><div class="segmented assessment-mode" aria-label="选择16PF版本">${[['original','原版'],['ai','AI 重置版']].map(([id,label])=>B(label,'mode',{cls:s.mode===id?'selected':'','data-id':id,'aria-pressed':s.mode===id})).join('')}</div>${B(!ProductContext.fixture?'暂不可开始':ai?'开始 AI 重置版':unfinished?'继续上次作答':done?'回看这次作答':'开始原版测评',action,{cls:'btn full home-assessment-start',after:ProductContext.fixture?'arrow':'',disabled:!ProductContext.fixture,...params})}${!ProductContext.fixture?`<p class="small muted space-12">当前没有可用题目。可以先从具体经历认识自己。</p>${L('先整理一个生活问题','explore',{cls:'textbtn full space-8',after:'arrow'})}`:''}${!ai&&unfinished?`<p class="home-resume-note">已保存 ${Object.keys(sess.answers).length} 个回答</p>`:''}</div></section>
  <section class="home-paths" aria-label="其他探索方式"><div class="home-secondary-grid">${[['single-factor','bottle','单因子测评','选一个想了解的角度'],['daily-checkin','sun','每日打卡','留意今天的自己'],['short-16pf','book','简化16PF','从情境问题出发'],['personality-sandbox','explore','模拟性格','设定一组假想倾向']].map(([r,i,t,d])=>L(`${icon(i)}<strong>${t}</strong><small>${d}</small>`,r,{cls:'home-path'})).join('')}</div></section>${a?L(`${icon('flag')}<span class="grow"><strong>回看自己的小尝试</strong><small>${esc(a.text)}</small></span>${icon('arrow','sm')}`,'action-detail',{cls:'v3-action-resume','data-id':a.id}):''}`;
 }
 function stage(route){
  if(!ProductContext.fixture)return `<section class="preview-paper">${UI.empty('暂时没有可用题目','可以先记录与这个问题有关的一件事。',L('写一条观察','journal',{cls:'btn secondary'}))}</section>`;
  const result=state.screen[route]==='result',selected=state.answer[route];
  return `<section class="preview-paper"><div class="preview-section-head"><h2>${result?'这次作答':'回答问题'}</h2>${tag('')}</div>${result?`<div class="preview-empty">${icon('book')}<h3>这里将呈现你的探索</h3><p>还没有可查看的解读。</p></div>${B('回看回答','preview-stage',{cls:'btn secondary full','data-id':route,'data-stage':'process'})}`:`<p class="small muted">1 / ${route==='daily-checkin'?state.count:'—'}</p><h3 class="space-16">遇到一个新的安排，你更愿意先做什么？</h3><p class="small muted"></p><div class="preview-options" role="group" aria-label="选项">${[['a','先弄清楚具体要求'],['b','先想想自己的感受'],['c','看看情况，再决定']].map(([id,t])=>B(t,'preview-answer',{cls:'option '+(selected===id?'selected':''),'data-id':route,'data-value':id,'aria-pressed':String(selected===id)})).join('')}</div><p class="small muted" role="status">${selected?'已选择':'选择更接近自己的回答。'}</p>${B('完成本次作答','preview-stage',{cls:'btn secondary full space-16','data-id':route,'data-stage':'result',disabled:!selected})}`}</section>${B('返回','preview-stage',{cls:'textbtn full','data-id':route,'data-stage':'config'})}`;
 }
 function single(){const route='single-factor',f=D.factors.find(f=>f[0]===state.factor);return head(route,'一次只看一个角度，选择你想进一步了解的因子。')+(state.screen[route]&&state.screen[route]!=='config'?stage(route):`<section class="preview-paper"><div class="preview-section-head"><h2>选择一个因子</h2><span>${f?'已选 1 / 16':'尚未选择'}</span></div><div class="factor-picker">${D.factors.map(f=>B(`${bottle([f[0],f[1],null,f[3]])}<strong>${esc(f[1])}</strong><small>${f[0]}</small>`,'preview-factor',{cls:'factor-choice '+(f[0]===state.factor?'selected':''),'data-id':f[0],'aria-pressed':String(f[0]===state.factor),'aria-label':f[0]+' '+f[1]})).join('')}</div><div class="preview-selection" role="status"><h3>${f?esc(f[0]+' · '+f[1]):'先选一个想了解的角度'}</h3><p>${f?esc(f[4])+'。可以结合自己的具体经历进一步了解。':'选一个想进一步了解的角度。'}</p></div>${ProductContext.fixture?B('开始作答','preview-stage',{cls:'btn secondary full','data-id':route,'data-stage':'process',disabled:!f}):''}${f?B('清除选择','preview-clear-factor',{cls:'textbtn full'}):''}</section>${unavailable('开始正式单因子测评','正式题源、映射与计分尚未接入。预览选择不会新建答卷。')}`);}
 function daily(){const route='daily-checkin';return head(route,'每天留一点时间，看看今天的自己。')+(state.screen[route]&&state.screen[route]!=='config'?stage(route):`<section class="preview-paper">${UI.empty('今天还没有可用的问题','也可以留下一件今天在意的小事。',L('写一条观察','journal',{cls:'btn secondary','data-kind':'daily'}))}${ProductContext.fixture?`<fieldset class="preview-fieldset"><legend>今天回答几个问题</legend><div class="preview-count">${[3,4,5].map(n=>B(n+' 题','preview-count',{cls:n===state.count?'selected':'','data-value':n,'aria-pressed':n===state.count})).join('')}</div></fieldset>${controls(route)}`:''}</section>`);}
 function short(){const route='short-16pf';return head(route,'从情境问题出发，留意自己的想法与选择。')+(state.screen[route]&&state.screen[route]!=='config'?stage(route):`<section class="preview-paper">${UI.empty('暂时没有可用题目','先看看最近想理清的生活问题。',L('去探索','explore',{cls:'btn secondary'}))}${controls(route)}</section>`);}
 function sandbox(){const route='personality-sandbox',count=Object.keys(state.scores).length;return head(route,'调整16个因子，设定一种假想性格。')+(state.screen[route]==='result'?`<section class="preview-paper"><h2>这组假设设定</h2><p>回看刚才设定的位置，也可以继续调整。</p><div class="preview-score-summary">${D.factors.map(f=>`<div><span>${esc(f[0]+' '+f[1])}</span><strong>${state.scores[f[0]]??'未设置'}</strong></div>`).join('')}</div><div class="preview-empty"><h3>还没有可用的解读</h3><p>可以先保留这些位置，换个角度继续设想。</p></div>${B('继续调整假设','preview-stage',{cls:'btn secondary full','data-id':route,'data-stage':'config'})}</section>`:`<section class="preview-paper"><div class="preview-section-head"><h2>16个因子，自己设定</h2><span id="sandbox-count">已设置 ${count} / 16</span></div><p id="sandbox-scale" class="preview-boundary">0–10表示这次假设的位置。滑杆初始中点未选定；未设置的角度会保持空白。</p><div class="preview-sliders">${D.factors.map(f=>`<div class="preview-slider"><label for="hypothesis-${f[0]}">${esc(f[0]+' · '+f[1])}</label><output for="hypothesis-${f[0]}" id="value-${f[0]}">${state.scores[f[0]]??'未设置'}</output><input id="hypothesis-${f[0]}" type="range" min="0" max="10" step="1" value="${state.scores[f[0]]??5}" data-preview-score="${f[0]}" aria-describedby="sandbox-scale"><div class="slider-extents"><span>0 · 低位</span><span>10 · 高位</span></div></div>`).join('')}</div>${B('查看假设配置','preview-stage',{cls:'btn secondary full','data-id':route,'data-stage':'result'})}${B('清空全部假设值','preview-clear-scores',{cls:'textbtn full'})}<p class="small muted">这组设定只在当前页面保留，刷新后清空。</p></section>${unavailable('分析假设性格','分析服务尚未接入。可先查看配置布局，不生成虚构AI结果。')}`);}
 function ai(){return head('ai-reset','从另一种提问方式，了解自己的倾向。')+`<section class="preview-paper">${UI.empty('暂时没有可用题目','你可以先回到认识，选择其他探索方式。',L('整理一个生活问题','explore',{cls:'btn secondary'}))}</section>`;}
 function repaintChoice(action,value){C.repaint();document.querySelector('[data-action="'+CSS.escape(action)+'"][data-value="'+CSS.escape(value)+'"]')?.focus({preventScroll:true});}
 function dispatch(action,el){const d=el?.dataset||{};switch(action){
  case 'preview-factor':if(D.factors.some(f=>f[0]===d.id)){state.factor=d.id;C.repaint();}return true;
  case 'preview-clear-factor':state.factor=null;C.repaint();return true;
  case 'preview-count':if([3,4,5].includes(Number(d.value))){state.count=Number(d.value);repaintChoice(action,d.value);}return true;
  case 'preview-answer':if(names[d.id]&&['a','b','c'].includes(d.value)){state.answer[d.id]=d.value;repaintChoice(action,d.value);}return true;
  case 'preview-stage':if(names[d.id]&&['config','process','result'].includes(d.stage)){state.screen[d.id]=d.stage;C.repaint();document.querySelector('.preview-paper h2')?.setAttribute('tabindex','-1');document.querySelector('.preview-paper h2')?.focus();}return true;
  case 'preview-clear-scores':state.scores={};C.repaint();C.toast('已清空这组假设值。');return true;
  default:return false;
 }}
 document.addEventListener('input',e=>{const code=e.target.dataset.previewScore;if(!D.factors.some(f=>f[0]===code))return;state.scores[code]=Math.min(10,Math.max(0,Number(e.target.value)));document.getElementById('value-'+code).textContent=state.scores[code];document.getElementById('sandbox-count').textContent='已设置 '+Object.keys(state.scores).length+' / 16';});
 Object.assign(Views.map,{'single-factor':single,'daily-checkin':daily,'short-16pf':short,'personality-sandbox':sandbox,'ai-reset':ai});
 return {home,getStage(){return state.screen[C?.current().split('?')[0]]||'config';},isQuiet(){return C&&state.screen[C.current().split('?')[0]]==='process';},bind(c){C=c;},dispatch,afterRender(){const r=C.current().split('?')[0];if(names[r])document.title=names[r]+' · 知遇测评';}};
})();
